import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import toast from 'react-hot-toast';

import {
  updateFormField,
  createComplaint,
  updateComplaint,
  setFormData,
} from '../../store/slices/complaintSlice';

const EMPTY_FORM = {
  complaint_source: '',

  complainant_name: '',
  complainant_company: '',
  complainant_email: '',
  complainant_phone: '',

  product_name: '',
  product_strength: '',
  batch_number: '',
  manufacturing_date: '',
  expiry_date: '',
  quantity_affected: '',

  complaint_type: '',
  complaint_date: '',

  description: '',

  severity: '',
  priority: '',

  assigned_to: '',
  status: 'Pending Triage',

  source: 'Manual',
};


const COMPLAINT_TYPES = [
  'Quality',
  'Packaging',
  'Efficacy',
  'Safety',
  'Labeling',
  'Other',
];

const SEVERITIES = [
  'Critical',
  'Major',
  'Minor',
];

const PRIORITIES = [
  'High',
  'Medium',
  'Low',
];

const COMPLAINT_SOURCES = [
  'Email',
  'Phone',
  'Portal',
  'Distributor',
  'Hospital',
  'Customer',
];

const STATUSES = [
  'Open',
  'Under Investigation',
  'Pending CAPA',
  'Closed',
];

function Field({
  label,
  field,
  value,
  onChange,
  type = 'text',
  options,
}) {
  return (
    <div>

      <label className="block mb-1 text-xs font-medium text-gray-500">
        {label}
      </label>

      {options ? (
        <select
          value={value}
          onChange={(e) => onChange(field, e.target.value)}
          className="w-full border rounded-lg px-3 py-2"
        >
          <option value="">
    Awaiting AI extraction...
</option>

          {options.map((item) => (
            <option key={item} value={item}>
              {item}
            </option>
          ))}

        </select>
      ) : type === 'textarea' ? (
        <textarea
          placeholder="Awaiting AI extraction..."
          value={value}
          onChange={(e) => onChange(field, e.target.value)}
          className="w-full border rounded-lg px-3 py-2 h-24"
        />
      ) : (
        <input
          placeholder="Awaiting AI extraction..."
          type={type}
          value={value}
          onChange={(e) => onChange(field, e.target.value)}
          className="w-full border rounded-lg px-3 py-2"
        />
      )}

    </div>
  );
}

export default function ComplaintForm({ isEdit = false }) {

  const dispatch = useDispatch();

  const form = useSelector(
    (state) => state.complaints.currentComplaint
  );

  const handleChange = (field, value) => {
    dispatch(updateFormField({ field, value }));
  };

  const clearForm = () => {
    dispatch(setFormData(EMPTY_FORM));
    toast.success('Form cleared');
  };

  const handleSave = async () => {
    try {

      if (isEdit && form.id) {

        await dispatch(
          updateComplaint({
            id: form.id,
            data: form,
          })
        ).unwrap();

        toast.success('Complaint updated');

      } else {

        await dispatch(createComplaint(form)).unwrap();

        toast.success('Complaint created');

        dispatch(setFormData(EMPTY_FORM));
      }

    } catch {

      toast.error('Unable to save complaint');

    }
  };

  return (
    <div className="bg-white rounded-xl border p-6">

      <div className="flex justify-between items-start mb-8">

    <div>

        <h2 className="text-3xl font-bold text-gray-800">
            Log Customer Complaint
        </h2>

        <p className="text-gray-500 mt-1">
            API & FDF Quality Assurance Module
        </p>

    </div>

    <span className="px-5 py-2 rounded-lg bg-yellow-50 border border-yellow-300 text-yellow-700 font-medium">
        Pending Triage
    </span>

</div>

      <div className="grid md:grid-cols-2 gap-4">
<div className="md:col-span-2">

    <h3 className="uppercase tracking-wide text-sm text-gray-500 font-semibold border-b pb-2 mb-5">

        1. ORIGIN & CUSTOMER DETAILS

    </h3>

</div>
        <Field
          label="Customer Name"
          field="complainant_name"
          value={form.complainant_name}
          onChange={handleChange}
        />

        <Field
          label="Company"
          field="complainant_company"
          value={form.complainant_company}
          onChange={handleChange}
        />

        <Field
          label="Email"
          field="complainant_email"
          value={form.complainant_email}
          onChange={handleChange}
        />

        <Field
          label="Phone"
          field="complainant_phone"
          value={form.complainant_phone}
          onChange={handleChange}
        />

        <Field
          label="Product"
          field="product_name"
          value={form.product_name}
          onChange={handleChange}
        />

        <Field
          label="Batch"
          field="batch_number"
          value={form.batch_number}
          onChange={handleChange}
        />

        <Field
          label="Category"
          field="category"
          value={form.category}
          options={CATEGORIES}
          onChange={handleChange}
        />

        <Field
          label="Severity"
          field="severity"
          value={form.severity}
          options={SEVERITIES}
          onChange={handleChange}
        />

        <div className="md:col-span-2">
          <Field
            label="Description"
            field="description"
            value={form.description}
            type="textarea"
            onChange={handleChange}
          />
        </div>

        <Field
          label="Assigned To"
          field="assigned_to"
          value={form.assigned_to}
          onChange={handleChange}
        />

        <Field
          label="Status"
          field="status"
          value={form.status}
          options={STATUSES}
          onChange={handleChange}
        />

      </div>

      <div className="flex justify-end gap-3 mt-6">

        <button
          onClick={clearForm}
          className="border px-4 py-2 rounded-lg"
        >
          Clear
        </button>

        <button
          onClick={handleSave}
          className="bg-blue-600 text-white px-5 py-2 rounded-lg"
        >
          {isEdit ? 'Update' : 'Save'}
        </button>

      </div>

    </div>
  );
}
